/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `audit_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '审计日志ID（建议永不删除，只归档）',
  `actor_user_id` bigint NOT NULL COMMENT '操作者用户ID',
  `action` varchar(64) NOT NULL COMMENT '动作：rule.update/grade.update/makeup.approve/role.change等',
  `entity_type` varchar(32) NOT NULL COMMENT '实体类型：student_profile/daily_record/warning_rule/warning/role等',
  `entity_id` bigint NOT NULL COMMENT '实体ID',
  `before_json` json DEFAULT NULL COMMENT '变更前（建议脱敏）',
  `after_json` json DEFAULT NULL COMMENT '变更后（建议脱敏）',
  `ip` varchar(64) DEFAULT NULL COMMENT 'IP',
  `user_agent` varchar(255) DEFAULT NULL COMMENT 'UA',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `action_desc` varchar(255) DEFAULT NULL COMMENT '操作描述（中文）',
  `entity_desc` varchar(255) DEFAULT NULL COMMENT '实体描述（中文）',
  PRIMARY KEY (`id`),
  KEY `audit_logs_actor_user_id_created_at_idx` (`actor_user_id`,`created_at`),
  KEY `audit_logs_entity_type_entity_id_idx` (`entity_type`,`entity_id`),
  KEY `audit_logs_action_created_at_idx` (`action`,`created_at`),
  KEY `audit_logs_created_at_idx` (`created_at`),
  KEY `audit_logs_entity_type_created_at_idx` (`entity_type`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=10412 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='审计日志';
/*!40101 SET character_set_client = @saved_cs_client */;

