--
-- Table structure for table `auth_challenges`
--

DROP TABLE IF EXISTS `auth_challenges`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `auth_challenges` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '验证码挑战ID（发一次验证码就插一条）',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID（可选；允许先发到手机号/邮箱再绑定）',
  `purpose` varchar(32) NOT NULL COMMENT '用途：login_admin登录 / approve_sensitive敏感审批等',
  `channel` varchar(16) NOT NULL COMMENT '渠道：sms短信 / email邮件',
  `target` varchar(128) NOT NULL COMMENT '手机号或邮箱（展示建议脱敏）',
  `code_hash` char(64) NOT NULL COMMENT '验证码hash（sha256(盐+code)；明文不落库）',
  `salt` varchar(32) NOT NULL COMMENT '盐（用于hash）',
  `status` varchar(16) NOT NULL COMMENT 'sent已发送 / verified已验证 / expired过期 / locked锁定',
  `expire_at` datetime(3) NOT NULL,
  `verified_at` datetime(3) DEFAULT NULL,
  `send_provider` varchar(32) DEFAULT NULL COMMENT '服务商：aliyun/baidu/smtp/mock',
  `send_msg_id` varchar(128) DEFAULT NULL COMMENT '服务商回执ID（可选）',
  `try_count` int NOT NULL DEFAULT '0' COMMENT '输入错误次数（超过阈值锁定）',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `auth_challenges_target_created_at_idx` (`target`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=391 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='2FA验证码挑战';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `auth_challenges`
--

LOCK TABLES `auth_challenges` WRITE;
/*!40000 ALTER TABLE `auth_challenges` DISABLE KEYS */;
