--
-- Table structure for table `calendar_exclusions`
--

DROP TABLE IF EXISTS `calendar_exclusions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `calendar_exclusions` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '排除日ID（节假日/特殊日期）',
  `scope` varchar(16) NOT NULL DEFAULT 'school' COMMENT '作用域：school/college',
  `scope_id` bigint DEFAULT NULL COMMENT '学院org_id（可选）',
  `exclusion_date` date NOT NULL COMMENT '排除日期（这天不计入累计）',
  `reason` varchar(255) DEFAULT NULL COMMENT '原因（节假日/停课/校运会等）',
  `created_by` bigint NOT NULL COMMENT '创建人用户ID',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `calendar_exclusions_scope_scope_id_exclusion_date_key` (`scope`,`scope_id`,`exclusion_date`),
  KEY `calendar_exclusions_exclusion_date_idx` (`exclusion_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='节假日/特殊日期排除';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `calendar_exclusions`
--

LOCK TABLES `calendar_exclusions` WRITE;
/*!40000 ALTER TABLE `calendar_exclusions` DISABLE KEYS */;
/*!40000 ALTER TABLE `calendar_exclusions` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `change_requests`
--

DROP TABLE IF EXISTS `change_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `change_requests` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '关键信息变更申请ID',
  `requester_user_id` bigint NOT NULL COMMENT '申请人用户ID（users.id）',
  `target_type` varchar(32) NOT NULL COMMENT '目标类型：student_profile/user/class等',
  `target_id` bigint NOT NULL COMMENT '目标ID',
  `change_json` json NOT NULL COMMENT '变更内容（字段->新值；或from/to结构）',
  `reason` varchar(255) DEFAULT NULL COMMENT '变更原因',
  `status` varchar(16) NOT NULL DEFAULT 'submitted' COMMENT 'submitted提交 / approved通过 / rejected驳回 / applied已生效',
  `approver_user_id` bigint DEFAULT NULL COMMENT '审批人用户ID',
  `approved_at` datetime(3) DEFAULT NULL,
  `rejected_at` datetime(3) DEFAULT NULL,
  `reject_reason` varchar(255) DEFAULT NULL COMMENT '驳回原因',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `change_requests_target_type_target_id_idx` (`target_type`,`target_id`),
  KEY `change_requests_status_idx` (`status`),
  KEY `change_requests_requester_user_id_created_at_idx` (`requester_user_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='关键信息变更审批';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `change_requests`
--

