CREATE TABLE `daily_records` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '每日学业记录ID（预警引擎主要用它）',
  `student_id` bigint NOT NULL COMMENT '学生档案ID（student_profiles.id）',
  `record_date` date NOT NULL COMMENT '记录日期（YYYY-MM-DD）',
  `class_id` bigint NOT NULL COMMENT '班级ID（冗余字段：按班查更快）',
  `org_id` bigint NOT NULL COMMENT '学院org_id（冗余字段：按学院统计更快）',
