  `homework_status` varchar(16) NOT NULL COMMENT '作业：on_time/late_submit/not_submit/unknown',
  `class_behavior` varchar(16) DEFAULT NULL COMMENT '课堂表现：active/passive/disruptive（可选）',
  `remarks` varchar(500) DEFAULT NULL COMMENT '备注（最多500字）',
  `source` varchar(16) NOT NULL COMMENT '来源：auto课表生成 / scan扫码 / manual补录',
  `approved_status` varchar(16) NOT NULL COMMENT '审批状态：approved/pending/rejected（manual补录时）',
  `approved_by` bigint DEFAULT NULL COMMENT '审批人用户ID（users.id）',
  `approved_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `daily_records_student_id_record_date_course_id_key` (`student_id`,`record_date`,`course_id`) COMMENT '防止同一天同课程重复写',
  KEY `daily_records_class_id_record_date_idx` (`class_id`,`record_date`),
  KEY `daily_records_org_id_record_date_idx` (`org_id`,`record_date`),
  KEY `daily_records_student_id_record_date_idx` (`student_id`,`record_date`),
  KEY `daily_records_student_id_attendance_status_record_date_cours_idx` (`student_id`,`attendance_status`,`record_date`,`course_id`),
  CONSTRAINT `daily_records_student_id_fkey` FOREIGN KEY (`student_id`) REFERENCES `student_profiles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6824 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='每日学业记录（最小粒度=天）';
