--
-- Table structure for table `files`
--

DROP TABLE IF EXISTS `files`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `files` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文件ID',
  `uploader_user_id` bigint NOT NULL COMMENT '上传人用户ID（users.id）',
  `file_name` varchar(256) NOT NULL COMMENT '原始文件名',
  `file_key` varchar(512) NOT NULL COMMENT '对象存储Key（MinIO/OSS/COS）',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小（字节）',
  `mime_type` varchar(128) DEFAULT NULL COMMENT 'MIME类型（image/png、application/pdf等）',
  `sha256` char(64) DEFAULT NULL COMMENT '文件sha256（可选：完整性校验）',
  `source` varchar(32) NOT NULL DEFAULT 'upload' COMMENT '来源：upload上传 / report报表 / proof证明 / import导入等',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `files_file_key_key` (`file_key`),
  KEY `files_uploader_user_id_created_at_idx` (`uploader_user_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='文件元数据';
/*!40101 SET character_set_client = @saved_cs_client */;

