--
-- Table structure for table `monthly_summaries`
--

DROP TABLE IF EXISTS `monthly_summaries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `monthly_summaries` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '月汇总ID（定时任务生成）',
  `student_id` bigint NOT NULL COMMENT '学生档案ID',
  `year` int NOT NULL COMMENT '年份',
  `month` int NOT NULL COMMENT '月份（1-12）',
  `late_count` int NOT NULL DEFAULT '0' COMMENT '本月迟到次数',
  `absent_count` int NOT NULL DEFAULT '0' COMMENT '本月缺勤次数',
  `homework_not_submit_count` int NOT NULL DEFAULT '0' COMMENT '本月未交作业次数',
  `generated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `monthly_summaries_student_id_year_month_key` (`student_id`,`year`,`month`),
  KEY `monthly_summaries_year_month_idx` (`year`,`month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学生月汇总（红色预警数据源）';
/*!40101 SET character_set_client = @saved_cs_client */;

