--
-- Table structure for table `notification_jobs`
--

DROP TABLE IF EXISTS `notification_jobs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_jobs` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '通知任务ID（入队后由worker消费）',
  `trigger_type` varchar(16) NOT NULL COMMENT '触发类型：rule规则触发 / manual人工发送',
  `warning_id` bigint DEFAULT NULL COMMENT '关联预警ID（规则触发时有）',
  `sender_user_id` bigint DEFAULT NULL COMMENT '发送人用户ID（人工发送时有）',
  `channel` varchar(16) NOT NULL COMMENT '渠道：sms/wechat/wecom/email/app',
  `template_code` varchar(64) DEFAULT NULL COMMENT '模板编码（可选）',
  `receivers_json` json NOT NULL COMMENT '接收人列表（结构化：type+id+addr）',
  `params_json` json DEFAULT NULL COMMENT '模板参数（渲染用）',
  `schedule_at` datetime(3) DEFAULT NULL,
  `cooldown_key` varchar(128) DEFAULT NULL COMMENT '频控键（如 student_id+level+rule_id+period）',
  `status` varchar(16) NOT NULL COMMENT 'queued排队 / running发送中 / success成功 / failed失败 / cancelled取消',
  `try_count` int NOT NULL DEFAULT '0' COMMENT '重试次数',
  `last_error` varchar(255) DEFAULT NULL COMMENT '失败原因（可选）',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `notification_jobs_status_created_at_idx` (`status`,`created_at`),
  KEY `notification_jobs_status_schedule_at_idx` (`status`,`schedule_at`),
  KEY `notification_jobs_warning_id_channel_idx` (`warning_id`,`channel`)
) ENGINE=InnoDB AUTO_INCREMENT=2901 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='通知发送任务（异步队列）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `notification_jobs`
--

