--
-- Table structure for table `notification_logs`
--

DROP TABLE IF EXISTS `notification_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '通知发送日志ID（审计）',
  `job_id` bigint NOT NULL COMMENT '通知任务ID（notification_jobs.id）',
  `channel` varchar(16) NOT NULL COMMENT '渠道',
  `receiver` varchar(128) NOT NULL COMMENT '接收地址（手机号/openid/邮箱等；展示建议脱敏）',
  `content_snapshot` text COMMENT '发送内容快照（敏感可脱敏存）',
  `send_status` varchar(16) NOT NULL COMMENT '发送状态：success/failed',
  `provider` varchar(32) DEFAULT NULL COMMENT '服务商：aliyun/baidu/wechat/smtp等',
  `provider_msg_id` varchar(128) DEFAULT NULL COMMENT '服务商消息ID/回执ID',
  `error_msg` varchar(255) DEFAULT NULL COMMENT '失败原因',
  `sent_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `acknowledged` tinyint(1) NOT NULL DEFAULT '0',
  `acknowledged_at` datetime(3) DEFAULT NULL,
  `acknowledged_by` bigint DEFAULT NULL COMMENT '确认人用户ID',
  PRIMARY KEY (`id`),
  KEY `notification_logs_job_id_idx` (`job_id`),
  KEY `notification_logs_sent_at_idx` (`sent_at`),
  KEY `notification_logs_send_status_sent_at_idx` (`send_status`,`sent_at`),
  KEY `notification_logs_channel_sent_at_idx` (`channel`,`sent_at`),
  KEY `notification_logs_receiver_sent_at_idx` (`receiver`,`sent_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2141 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='通知发送日志（含确认/回执）';
/*!40101 SET character_set_client = @saved_cs_client */;

