--
-- Table structure for table `orgs`
--

DROP TABLE IF EXISTS `orgs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orgs` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '组织ID（学校/学院/部门等）',
  `name` varchar(128) NOT NULL COMMENT '组织名称（如XX大学、计算机学院）',
  `org_kind` varchar(16) NOT NULL DEFAULT 'school' COMMENT '组织类型：school学校 / college学院 / office部门 / other其他',
  `org_level` int NOT NULL DEFAULT '1' COMMENT '组织层级：学校=1、学院=2（可扩展）',
  `parent_org_id` bigint DEFAULT NULL COMMENT '上级组织ID（学院parent指向学校）',
  `status` varchar(16) NOT NULL DEFAULT 'active' COMMENT '状态：active启用 / disabled停用',
  `meta_json` json DEFAULT NULL COMMENT '扩展信息（联系人、电话、地址等）',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `orgs_parent_org_id_idx` (`parent_org_id`),
  KEY `orgs_org_kind_org_level_idx` (`org_kind`,`org_level`),
  KEY `orgs_status_idx` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='组织（学校/学院/部门）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
