--
-- Table structure for table `student_profiles`
--

DROP TABLE IF EXISTS `student_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_profiles` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '学生档案ID（学生业务数据建议放这里）',
  `user_id` bigint NOT NULL COMMENT '对应用户ID（users.id，学生端绑定后写入）',
  `student_no` varchar(64) NOT NULL COMMENT '学号（唯一）',
  `gender` varchar(8) DEFAULT NULL COMMENT '性别（可选）',
  `photo_file_id` bigint DEFAULT NULL COMMENT '证件照文件ID（files.id，可选）',
  `class_id` bigint NOT NULL COMMENT '班级ID（classes.id）',
  `org_id` bigint DEFAULT NULL COMMENT '学院org_id（冗余字段，便于按学院统计；可由class反查）',
  `major` varchar(128) DEFAULT NULL COMMENT '专业（冗余字段，可由class.major）',
  `enroll_year` int DEFAULT NULL COMMENT '入学年份（冗余字段）',
  `mobile` varchar(32) DEFAULT NULL COMMENT '手机号（敏感）',
  `email` varchar(128) DEFAULT NULL COMMENT '邮箱（敏感）',
  `emergency_contact_name` varchar(64) DEFAULT NULL COMMENT '紧急联系人姓名（敏感）',
  `emergency_contact_mobile` varchar(32) DEFAULT NULL COMMENT '紧急联系人电话（敏感）',
  `notify_prefs_json` json DEFAULT NULL COMMENT '通知偏好（渠道开关/静默时段等）',
  `status` varchar(16) NOT NULL COMMENT '状态：active在读 / graduated毕业 / disabled停用',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `initial_password` varchar(128) DEFAULT NULL,
  `student_position` varchar(32) DEFAULT NULL,
  `wx_openid` varchar(64) DEFAULT NULL,
  `wx_unionid` varchar(64) DEFAULT NULL,
  `major_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `student_profiles_student_no_key` (`student_no`),
  UNIQUE KEY `student_profiles_user_id_key` (`user_id`),
  KEY `student_profiles_class_id_fkey` (`class_id`),
  KEY `student_profiles_major_id_idx` (`major_id`),
  KEY `student_profiles_org_id_idx` (`org_id`),
  KEY `student_profiles_status_idx` (`status`),
  KEY `student_profiles_class_id_status_student_no_idx` (`class_id`,`status`,`student_no`),
  CONSTRAINT `student_profiles_class_id_fkey` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `student_profiles_major_id_fkey` FOREIGN KEY (`major_id`) REFERENCES `majors` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `student_profiles_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=25227 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学生档案';
/*!40101 SET character_set_client = @saved_cs_client */;

