CREATE TABLE `student_warning_snapshots` (
  `student_id` bigint NOT NULL,
  `class_id` bigint NOT NULL,
  `org_id` bigint NOT NULL,
  `today_warning_total` int NOT NULL DEFAULT '0',
  `week_warning_total` int NOT NULL DEFAULT '0',
  `month_warning_total` int NOT NULL DEFAULT '0',
  `active_warning_count` int NOT NULL DEFAULT '0',
  `closed_warning_count` int NOT NULL DEFAULT '0',
