  `all_highest_level` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `active_last_warning_at` datetime(3) DEFAULT NULL,
  `closed_last_warning_at` datetime(3) DEFAULT NULL,
  `all_last_warning_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`student_id`),
  KEY `student_warning_snapshots_class_id_idx` (`class_id`),
