--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户ID（学生/老师/管理人员）',
  `org_id` bigint DEFAULT NULL COMMENT '所属组织（老师/管理端用户）',
  `user_type` varchar(16) NOT NULL COMMENT '用户类型：student学生 / teacher老师 / staff学工 / admin系统管理员',
  `name` varchar(64) NOT NULL COMMENT '姓名',
  `mobile` varchar(32) DEFAULT NULL COMMENT '手机号（敏感：建议应用层加密/脱敏显示）',
  `email` varchar(128) DEFAULT NULL COMMENT '邮箱（敏感：建议应用层加密/脱敏显示）',
  `status` varchar(16) NOT NULL COMMENT '状态：active/disabled',
  `wx_openid` varchar(64) DEFAULT NULL COMMENT '微信openid（小程序端）',
  `wx_unionid` varchar(64) DEFAULT NULL COMMENT '微信unionid（统一身份）',
  `password_hash` varchar(255) DEFAULT NULL COMMENT '管理端密码hash（如使用账号密码登录）',
  `last_login_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `teacher_position` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `users_org_id_fkey` (`org_id`),
  KEY `users_mobile_idx` (`mobile`),
  KEY `users_email_idx` (`email`),
  KEY `users_wx_openid_idx` (`wx_openid`),
  KEY `users_user_type_idx` (`user_type`),
  KEY `users_status_idx` (`status`),
  CONSTRAINT `users_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `orgs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=25385 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `users`
--

LOCK TABLES `users` WRITE;
/*!40000 ALTER TABLE `users` DISABLE KEYS */;
