DROP TABLE IF EXISTS `warning_cases`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `warning_cases` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `class_id` bigint NOT NULL,
  `org_id` bigint NOT NULL,
  `primary_warning_id` bigint DEFAULT NULL,
  `source_warning_ids_json` json DEFAULT NULL,
  `risk_score` int NOT NULL DEFAULT '0',
  `risk_breakdown_json` json DEFAULT NULL,
  `warning_summary_json` json DEFAULT NULL,
  `handling_priority` int NOT NULL DEFAULT '0',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending_assignment',
  `handler_user_id` bigint DEFAULT NULL,
  `assigned_by` bigint DEFAULT NULL,
  `assigned_at` datetime(3) DEFAULT NULL,
  `accepted_at` datetime(3) DEFAULT NULL,
  `completed_at` datetime(3) DEFAULT NULL,
  `resolved_at` datetime(3) DEFAULT NULL,
  `completion_summary` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `completion_detail_json` json DEFAULT NULL,
  `latest_warning_at` datetime(3) DEFAULT NULL,
  `last_risk_at` datetime(3) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `warning_cases_student_id_is_active_idx` (`student_id`,`is_active`),
  KEY `warning_cases_status_is_active_idx` (`status`,`is_active`),
  KEY `warning_cases_handler_user_id_status_idx` (`handler_user_id`,`status`),
  KEY `warning_cases_class_id_status_idx` (`class_id`,`status`),
  KEY `warning_cases_org_id_status_idx` (`org_id`,`status`),
  KEY `warning_cases_class_id_is_active_updated_at_idx` (`class_id`,`is_active`,`updated_at`),
  KEY `warning_cases_org_id_is_active_updated_at_idx` (`org_id`,`is_active`,`updated_at`),
  KEY `warning_cases_class_id_created_at_idx` (`class_id`,`created_at`),
  KEY `warning_cases_org_id_created_at_idx` (`org_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
