DROP TABLE IF EXISTS `warning_current_states`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `warning_current_states` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `class_id` bigint NOT NULL,
  `org_id` bigint NOT NULL,
  `metric` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `level` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `window` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `course_key` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `course_id` bigint DEFAULT NULL,
  `rule_id` bigint NOT NULL,
  `rule_snapshot_json` json NOT NULL,
  `trigger_summary` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `trigger_detail_json` json DEFAULT NULL,
  `current_count` int NOT NULL DEFAULT '0',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `acknowledged_at` datetime(3) DEFAULT NULL,
  `acknowledged_by` bigint DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_warn_cur_state_course` (`student_id`,`metric`,`window`,`period_start`,`period_end`,`course_key`),
  KEY `warning_current_states_student_id_status_idx` (`student_id`,`status`),
  KEY `warning_current_states_student_id_period_start_period_end_up_idx` (`student_id`,`period_start`,`period_end`,`updated_at`),
  KEY `warning_current_states_class_id_status_idx` (`class_id`,`status`),
  KEY `warning_current_states_org_id_status_idx` (`org_id`,`status`),
  KEY `warning_current_states_org_id_level_idx` (`org_id`,`level`),
  KEY `warning_current_states_course_id_status_idx` (`course_id`,`status`),
  KEY `warning_current_states_status_course_id_updated_at_idx` (`status`,`course_id`,`updated_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4567 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
