--
-- Table structure for table `weekly_summaries`
--

DROP TABLE IF EXISTS `weekly_summaries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `weekly_summaries` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '周汇总ID（定时任务生成）',
  `student_id` bigint NOT NULL COMMENT '学生档案ID',
  `week_start` date NOT NULL COMMENT '周起始日期（周一）',
  `week_end` date NOT NULL COMMENT '周结束日期（周日）',
  `late_count` int NOT NULL DEFAULT '0' COMMENT '本周迟到次数',
  `absent_count` int NOT NULL DEFAULT '0' COMMENT '本周缺勤次数',
  `homework_not_submit_count` int NOT NULL DEFAULT '0' COMMENT '本周未交作业次数',
  `generated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `weekly_summaries_student_id_week_start_key` (`student_id`,`week_start`),
  KEY `weekly_summaries_week_start_week_end_idx` (`week_start`,`week_end`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学生周汇总（橙色预警数据源）';
/*!40101 SET character_set_client = @saved_cs_client */;

